import itertools
import unittest

import pricing

RATE = 0.0825


def ref_order(items):
    subtotal = sum(i["price"] * i["qty"] for i in items)
    tax = round(subtotal * RATE, 2)
    return round(subtotal + tax, 2)


def ref_invoice(items, shipping):
    subtotal = sum(i["price"] * i["qty"] for i in items)
    tax = round(subtotal * RATE, 2)
    return round(subtotal + tax + shipping, 2)


def ref_quote(items, discount):
    subtotal = sum(i["price"] * i["qty"] for i in items)
    subtotal = subtotal - discount
    tax = round(subtotal * RATE, 2)
    return round(subtotal + tax, 2)


CARTS = [
    [],
    [{"price": 0.99, "qty": 3}],
    [{"price": 19.99, "qty": 7}, {"price": 0.10, "qty": 1}],
    [{"price": 1234.56, "qty": 1}, {"price": 7.77, "qty": 13}],
]


class BehaviourUnchanged(unittest.TestCase):
    def test_order_total(self):
        for cart in CARTS:
            self.assertEqual(pricing.order_total(cart), ref_order(cart))

    def test_invoice_total(self):
        for cart, shipping in itertools.product(CARTS, [0, 4.99, 12]):
            self.assertEqual(pricing.invoice_total(cart, shipping), ref_invoice(cart, shipping))

    def test_quote_total(self):
        for cart, discount in itertools.product(CARTS, [0, 1.25, 10]):
            self.assertEqual(pricing.quote_total(cart, discount), ref_quote(cart, discount))

    def test_tax_rate_constant_still_exists(self):
        self.assertEqual(pricing.TAX_RATE, RATE)


if __name__ == "__main__":
    unittest.main()
